/*===========================================================================

FUNCTION tdsrrccu_intiate_cell_selection_within_fach_cu_cnf

DESCRIPTION 
  Sends a Initate Cell Selection for FACH->FACH.
  Also takes a backup of the ota contents which are 
  required for configuring the lower layers once the cell selection 
  is complete. 

DEPENDENCIES
  None

RETURN VALUE
  None

SIDE EFFECTS
  None
===========================================================================*/

static void tdsrrccu_intiate_cell_selection_within_fach_cu_cnf(   tdsrrc_cmd_type *cmd_ptr  )
{
  uint8 idx;
  /* Backup the channel config req contents */
  tdsrrccu_chan_config_info.num_rbs = cmd_ptr->cmd.chan_config_req.num_rb_to_config;
  tdsrrccu_chan_config_reqd = TRUE;
  
  tdsrrccu_int_data.rrccu_cell_selection_last_response_msg =   tdsrrccu_resp_msg;
  tdsrrccu_int_data.rrccu_cell_selection_last_trans_id = tdsrrccu_trans_id;
  
  tdsrrccu_int_data.rrccu_last_cucnf_for_srns_relocation= tdsrrccu_cucnf_for_srns_relocation ;
  tdsrrccu_int_data.rrccu_last_cucnf_cipher_update_required =tdsrrccu_cipher_update_required  ;
  TDSRRC_MSG2(MSG_LEGACY_HIGH,"Initiate Cell selection,response present to CU saved %d tran id %d",tdsrrccu_resp_msg,tdsrrccu_trans_id);
  for(idx =0;idx < cmd_ptr->cmd.chan_config_req.num_rb_to_config;idx++)
  {
    tdsrrccu_chan_config_info.rb_info[idx].rb_id = cmd_ptr->cmd.chan_config_req.rb[idx].rb_id;
    tdsrrccu_chan_config_info.rb_info[idx].rb_config = cmd_ptr->cmd.chan_config_req.rb[idx].rb_config;
    
  }
  /* Now copy OC to TOC */

  tdsrrcllcoc_update_toc_with_oc_from_fach();
  
    /*Initiate the cell selection*/
  tdsrrcrb_send_initiate_cell_selection_req( TDSRRC_PROCEDURE_CU,
                                         TDSRRC_TRANSITION_FROM_FACH,
                                        TDSRRC_STATE_CELL_FACH );
  
  
  tdsrrccu_substate = TDSRRCCU_WAIT_FOR_UE_TO_CAMP_ON;
   
  tdsrrccu_int_data.rrccu_cell_selection_trans_from_fach = TRUE;
  /*Not using the command for channel config right now so free it. */
  tdsrrc_free_cmd_buf(cmd_ptr);

}

/*===========================================================================

FUNCTION tdsrrccu_intiate_cell_selection_fach_pch_cu_cnf

DESCRIPTION
  Sends a Initate Cell Selection for FACH->PCH
DEPENDENCIES
  None

RETURN VALUE
  None

SIDE EFFECTS
  None
===========================================================================*/

static void tdsrrccu_intiate_cell_selection_fach_pch_cu_cnf(  void  )
{
  
  
  /* Now copy OC to TOC */
  tdsrrcllcoc_update_toc_with_oc_from_fach();

  if(tdsrrccu_state_indicator == tdsrrc_RRC_StateIndicator_cell_PCH )
  {
   tdsrrcrb_send_initiate_cell_selection_req(TDSRRC_PROCEDURE_CU,
                                    TDSRRC_TRANSITION_FROM_FACH,
                                    TDSRRC_STATE_CELL_PCH);
  }
  else
  {
   tdsrrcrb_send_initiate_cell_selection_req(TDSRRC_PROCEDURE_CU,
                                    TDSRRC_TRANSITION_FROM_FACH,
                                    TDSRRC_STATE_URA_PCH);
  }   
  
  TDSRRC_MSG0(MSG_LEGACY_HIGH,"Waiting for UE to camp on");
  tdsrrccu_substate = TDSRRCCU_WAIT_FOR_UE_TO_CAMP_ON;
}


/*===========================================================================

FUNCTION       tdsrrccu_check_and_send_response_to_previous_cell_upd_cnf

DESCRIPTION
   IF the Response to previous Cell Update Cnf is still pending, then it sends that response now.

DEPENDENCIES
  None

RETURN VALUE
  None

SIDE EFFECTS
  None
===========================================================================*/

static void  tdsrrccu_check_and_send_response_to_previous_cell_upd_cnf(void )
{
   /*   In the case where UE receives CU Cnf(for say CU 1) with Freq re-direction info to FACH, 
     * and having an response to send. CU will remember the Response details for CU 1, 
     * then intiate a cell selection.  If UE doesnt camp on directed cell, then it
     * configure Lower layers with OTA contents and then initate cell update (say cu 2)
     * with cause cell reselection. On receving CU CNF for CU 2, CU will send response
     * for CU 2, and then also send response for CU 1.
     * For this case CU needs to rember the response to be sent for 1 st CU .
     */
  if(tdsrrccu_int_data.rrccu_cell_selection_last_response_msg != TDSRRCCU_NO_RESP_MSG)
  {
     tdsrrccu_resp_msg = tdsrrccu_int_data.rrccu_cell_selection_last_response_msg ;
     tdsrrccu_int_data.rrccu_cell_selection_last_response_msg = TDSRRCCU_NO_RESP_MSG;
     tdsrrccu_trans_id = tdsrrccu_int_data.rrccu_cell_selection_last_trans_id ;
     tdsrrccu_cucnf_for_srns_relocation = tdsrrccu_int_data.rrccu_last_cucnf_for_srns_relocation;
     tdsrrccu_cipher_update_required = tdsrrccu_int_data.rrccu_last_cucnf_cipher_update_required;
     tdsrrccu_send_response_msg();
  }
}
/*===========================================================================

FUNCTION       tdsrrccu_init_last_cu_cnf_info

DESCRIPTION
   Initialises all the variables, which was required to send a response to the previous CU Cnf 
DEPENDENCIES
  None

RETURN VALUE
  None

SIDE EFFECTS
  None
===========================================================================*/
void tdsrrccu_init_last_cu_cnf_info(void )
{
  TDSRRC_MSG0(MSG_LEGACY_HIGH,"Initialised data for last CU response");
  tdsrrccu_int_data.rrccu_cell_selection_last_response_msg = TDSRRCCU_NO_RESP_MSG;
  tdsrrccu_int_data.rrccu_cell_selection_last_trans_id = 0xff;
  tdsrrccu_int_data.rrccu_last_cucnf_for_srns_relocation = FALSE;
  tdsrrccu_int_data.rrccu_last_cucnf_cipher_update_required = FALSE;
}
