/*===========================================================================

FUNCTION tdsrrccu_start_t_305_timer

DESCRIPTION
  This function is called during transition from CELL_DCH to CELL_FACH/
  CELL_PCH/URA_PCH to start the periodic cell update timer T_305
DEPENDENCIES
  None

RETURN VALUE
  None

SIDE EFFECTS
  None
===========================================================================*/
void  tdsrrccu_start_t_305_timer(void)
{
  unsigned long timer_value;

  timer_value = tdsrrc_convert_t305_to_ms(TDSRRC_GET_T305());
    
  if(timer_value == TDSRRCTMR_INFINITY_VAL )
  {
    TDSRRC_MSG2(MSG_LEGACY_HIGH,"T305 value infinity,dont start this timer rrc_st:%d,cu_st:%d ",tdsrrc_get_state(),tdsrrccu_substate);
  }
  else
  {
    TDSRRC_MSG3(MSG_LEGACY_HIGH,"Start T305 %ums rrc_st:%d, cu_st:%d", 
           timer_value,tdsrrc_get_state(),tdsrrccu_substate); 
    tdsrrctmr_start_timer(TDSRRCTMR_T_305_TIMER, 
                     timer_value); 
  }
  
}
