/*===========================================================================

FUNCTION tdsrrccu_fill_est_cause

DESCRIPTION
  This function will fill the establish cause in cell update.
  
DEPENDENCIES
  None

RETURN VALUE
  boolean
  TRUE  : OK to proceed with oc reset 
  FALSE :  Not OK to proceed with oc reset

SIDE EFFECTS
  None
===========================================================================*/


static void  tdsrrccu_fill_est_cause(tdsrrc_UL_CCCH_Message *loc_msg_ptr)
{




  rrc_establish_cause_e_type  est_cause;
  tdsrrc_EstablishmentCause trans_cause; /* translated to ASN format */

  rrc_call_type_in_est_req_e_type call_type;

 TDSRRC_MSG0(MSG_LEGACY_HIGH,"function fil_est called ");      
  if(tdsrrcidt_check_if_est_cause_available(TDSRRC_PROCEDURE_CU,&est_cause
                   ,&call_type
                              ) == TRUE)
  {
    TDSRRC_MSG0(MSG_LEGACY_HIGH,"filling cell update ");
  
    TDSRRC_MSG_COMMON_SET_BITMASK_IE(loc_msg_ptr->message.u.cellUpdate,tdsrrc_CellUpdate,
        laterNonCriticalExtensions);
  
    TDSRRC_RESET_MSG_IE_PRESENT(loc_msg_ptr->message.u.cellUpdate.laterNonCriticalExtensions);
  
    loc_msg_ptr->message.u.cellUpdate.laterNonCriticalExtensions.m.
     v590NonCriticalExtensionsPresent =1;
  
    //change_here  reset bit_mask to 0
    TDSRRC_RESET_MSG_IE_PRESENT(loc_msg_ptr->message.u.cellUpdate.laterNonCriticalExtensions.
      v590NonCriticalExtensions);
  
    TDSRRC_RESET_MSG_IE_PRESENT(loc_msg_ptr->message.u.cellUpdate.laterNonCriticalExtensions.v590NonCriticalExtensions.
        cellUpdate_v590ext);
  
   TDSRRC_MSG_COMMON_SET_BITMASK_IE_TYPE2(loc_msg_ptr->message.u.cellUpdate.laterNonCriticalExtensions.v590NonCriticalExtensions.
        cellUpdate_v590ext,establishmentCause);
    tdsrrc_translate_establishment_cause(est_cause, &trans_cause);
    loc_msg_ptr->message.u.cellUpdate.laterNonCriticalExtensions.v590NonCriticalExtensions.
         cellUpdate_v590ext.establishmentCause = trans_cause;
    tdsrrcidt_set_sent_by_cu(TDSRRC_PROCEDURE_CU);
      
    if (tdsrrc_nv_rel_indicator & TDSRRC_NV_REL_INDICATOR_REL7)
    {
      if(tdsrrcidt_is_cs_call_initiate() ==TRUE)
      {
        if(est_cause == RRC_EST_ORIG_CONV_CALL ||
            est_cause == RRC_EST_EMERGENCY_CALL)
        {
          loc_msg_ptr->message.u.cellUpdate.laterNonCriticalExtensions.v590NonCriticalExtensions.m.
           v690NonCriticalExtensionsPresent =1;
  
          TDSRRC_RESET_MSG_IE_PRESENT(loc_msg_ptr->message.u.cellUpdate.laterNonCriticalExtensions.v590NonCriticalExtensions.v690NonCriticalExtensions);
          
          loc_msg_ptr->message.u.cellUpdate.laterNonCriticalExtensions.v590NonCriticalExtensions.v690NonCriticalExtensions.
            m.v6b0NonCriticalExtensionsPresent =1;
  
          TDSRRC_RESET_MSG_IE_PRESENT(loc_msg_ptr->message.u.cellUpdate.laterNonCriticalExtensions.v590NonCriticalExtensions.v690NonCriticalExtensions.
            v6b0NonCriticalExtensions);
        
          loc_msg_ptr->message.u.cellUpdate.laterNonCriticalExtensions.v590NonCriticalExtensions.v690NonCriticalExtensions.
            v6b0NonCriticalExtensions.m.v770NonCriticalExtensionsPresent =1;
  
          TDSRRC_RESET_MSG_IE_PRESENT(loc_msg_ptr->message.u.cellUpdate.laterNonCriticalExtensions.v590NonCriticalExtensions.v690NonCriticalExtensions.
            v6b0NonCriticalExtensions.v770NonCriticalExtensions);
  
          TDSRRC_RESET_MSG_IE_PRESENT(loc_msg_ptr->message.u.cellUpdate.laterNonCriticalExtensions.v590NonCriticalExtensions.v690NonCriticalExtensions.
            v6b0NonCriticalExtensions.v770NonCriticalExtensions.cellUpdate_v770ext);
  
         TDSRRC_MSG_COMMON_SET_BITMASK_IE(loc_msg_ptr->message.u.cellUpdate.laterNonCriticalExtensions.v590NonCriticalExtensions.v690NonCriticalExtensions.
            v6b0NonCriticalExtensions.v770NonCriticalExtensions.cellUpdate_v770ext,
              tdsrrc_CellUpdate_v770ext_IEs,csCallType);
  
          TDSRRC_MSG2(MSG_LEGACY_HIGH,"Establishment cause : %d Call Type : %d " ,est_cause,call_type);
      
          switch(call_type)
          {
            case RRC_CALL_TYPE_SPEECH:
              loc_msg_ptr->message.u.cellUpdate.laterNonCriticalExtensions.v590NonCriticalExtensions.
                                   v690NonCriticalExtensions.v6b0NonCriticalExtensions.v770NonCriticalExtensions.
                                   cellUpdate_v770ext.csCallType = tdsrrc_CellUpdate_v770ext_IEs_csCallType_speech;
              break;
            case RRC_CALL_TYPE_VIDEO:
              loc_msg_ptr->message.u.cellUpdate.laterNonCriticalExtensions.v590NonCriticalExtensions.
                                   v690NonCriticalExtensions.v6b0NonCriticalExtensions.v770NonCriticalExtensions.
                                   cellUpdate_v770ext.csCallType = tdsrrc_CellUpdate_v770ext_IEs_csCallType_video;
              break;
            case RRC_CALL_TYPE_OTHERS:
              loc_msg_ptr->message.u.cellUpdate.laterNonCriticalExtensions.v590NonCriticalExtensions.
                                   v690NonCriticalExtensions.v6b0NonCriticalExtensions.v770NonCriticalExtensions.
                                   cellUpdate_v770ext.csCallType = tdsrrc_CellUpdate_v770ext_IEs_csCallType_other;
              break;
            default:
              TDSRRC_MSG1(MSG_LEGACY_ERROR,"Wrong est call type set by NAS = %d",call_type);
              loc_msg_ptr->message.u.cellUpdate.laterNonCriticalExtensions.v590NonCriticalExtensions.
                                   v690NonCriticalExtensions.v6b0NonCriticalExtensions.v770NonCriticalExtensions.
                                   cellUpdate_v770ext.csCallType = tdsrrc_CellUpdate_v770ext_IEs_csCallType_other;
              break;
          }
        }
      }
  
    }
  }
}
