/*===========================================================================

FUNCTION RRCCU_CHECK_PROC_WAITING_FOR_L2_ACK

DESCRIPTION
  This function will check the status of the procedure that has set the
  oc  

DEPENDENCIES
  None

RETURN VALUE
  boolean
  TRUE  : OK to proceed with oc reset 
  FALSE :  Not OK to proceed with oc reset

SIDE EFFECTS
  None
===========================================================================*/

static boolean tdsrrccu_check_proc_waiting_for_l2_ack (tdsrrc_proc_e_type proc_id)
{
  /*tdsrrcrb_substate_e_type sub_st = TDSRRCRB_MAX_SUBSTATES; */
  switch (proc_id)
  {
    case  TDSRRC_PROCEDURE_RBE:
    case  TDSRRC_PROCEDURE_RBR:
    case  TDSRRC_PROCEDURE_RBRC:
    case  TDSRRC_PROCEDURE_TCR:
    case  TDSRRC_PROCEDURE_PCR:
      if (TDSRRCRB_WAIT_FOR_L2_ACK == tdsrrcrb_get_proc_sub_state(proc_id))
      {
        return TRUE;
      } 
      else
      {
        return FALSE;
      }
    default:
      TDSRRC_MSG1(MSG_LEGACY_HIGH,"OC set by proc:%d",proc_id);
      return FALSE;
  }
}  /* tdsrrccu_check_proc_waiting_for_l2_ack */

