/*===========================================================================

FUNCTION RRCCU_CLEAR_PROCEDURE

DESCRIPTION
  This function will clear the global variables.

DEPENDENCIES
  None

RETURN VALUE
  None

SIDE EFFECTS
  None
===========================================================================*/
void tdsrrccu_clear_procedure
(    
  void  
)
{
  tdsrrccu_failure_state                   = TDSRRC_STATE_WILDCARD;
  tdsrrccu_chan_config_reqd                = FALSE;
  tdsrrccu_oc_set_by_cu                    = FALSE;
  tdsrrccu_rb_release_info.rrccu_rb_release_in_cucnf = FALSE;
  tdsrrccu_cell_update_cause               = tdsrrc_CellUpdateCause_cellUpdateCause_ext;
  tdsrrccu_ura_update_cause                = tdsrrc_URA_UpdateCause_spare1;
  tdsrrccu_cell_update_started             = FALSE;
  tdsrrccu_ura_update_started              = FALSE;
  tdsrrccu_ura_update_required             = FALSE;
#ifdef FEATURE_TDSCDMA_HSUPA
  tdsrrccu_rcv_mac_status_ind              = FALSE;
#endif
  
  tdsrrccu_rl_failure_info.t314_info.timer_status         = TDSRE_EST_TIMER_NOT_STARTED;
  tdsrrccu_rl_failure_info.t314_info.need_to_release_rabs = FALSE;
  tdsrrccu_rl_failure_info.t314_info.need_rab_release_ind = FALSE;
  tdsrrccu_rl_failure_info.t315_info.timer_status         = TDSRE_EST_TIMER_NOT_STARTED;
  tdsrrccu_rl_failure_info.t315_info.need_to_release_rabs = FALSE;
  tdsrrccu_rl_failure_info.t315_info.need_rab_release_ind = FALSE;
  tdsrrccu_rlc_error_info.error_on_srb = FALSE;
  tdsrrccu_rlc_error_info.error_on_urb = FALSE;

  tdsrrccu_cu_initiate_reqd.cu_reqd = FALSE;
 

  /*clear the global variables stored */
  tdsrrccu_cucnf_for_srns_relocation = FALSE;
  tdsrrccu_new_urnti_valid = FALSE;
  tdsrrccu_new_crnti_valid = FALSE;
  tdsrrccu_reestablish_srb = FALSE;
  tdsrrccu_reestablish_srb = FALSE;
  tdsrrccu_reestablish_rab = FALSE;
  tdsrrccu_reestablish_rab = FALSE;
  tdsrrccu_utran_drx_coef  = 0; 
 
  tdsrrccu_phy_chan_failure_from_rb = FALSE;

  tdsrrccu_cipher_update_required = FALSE;
  tdsrrccu_pending_config_proc_id = TDSRRC_PROCEDURE_NONE;
  tdsrrccu_rb_id_unrec_error = TDSRRC_INVALID_RB_ID; 
#ifdef FEATURE_RRC_FREQ_REDIRECTION_THRU_RB_AND_CU
  tdsrrccu_int_data.rrccu_cell_selection_trans_from_fach =FALSE;
  tdsrrccu_chan_config_info.num_rbs = 0;
#endif /*FEATURE_RRC_FREQ_REDIRECTION_THRU_RB_AND_CU*/

  tdsrrc_v_302 = 0;
  /* Reset buffered commands mask*/
  tdsrrccu_buffered_cmd_mask = 0;
  memset(&tdsrrccu_buffered_cu_initiate_req,0,sizeof(tdsrrc_initiate_cu_req_type));

} /* tdsrrccu_clear_procedure */

/*===========================================================================

FUNCTION tdsrrccu_check_rb_in_estab_rab

DESCRIPTION
  This function will check whether the rb is in established rabs, if so it returns
  true, else it returns false and clears cu state

DEPENDENCIES
  None

RETURN VALUE
  boolean
  TRUE  : rb is in established rabs
  FALSE : rb is not in established rabs 

SIDE EFFECTS
  None
===========================================================================*/

boolean tdsrrccu_check_rb_in_estab_rab
(
 void
)
{
  tdsrrc_RB_Identity rb_id =   tdsrrccu_rb_id_unrec_error;
  rlc_lc_id_type ul_rlc_lc_id = TDSRRCLCM_RLC_LC_ID_NOT_FOUND;

  if(TDSRRC_RB_PRESENT == tdsrrc_find_rb_in_est_rabs(rb_id))
  {
    return TRUE;
  }
  else if (rb_id == DCCH_DT_LOW_PRI_RADIO_BEARER_ID)
  {
    /* check whether RB4 is present or not */
    ul_rlc_lc_id = tdsrrclcm_check_ul_rlc_lc_id(UE_LOGCHAN_DCCH, 
                       DCCH_DT_LOW_PRI_RADIO_BEARER_ID,
                       UE_MODE_ACKNOWLEDGED_DATA);

    if(ul_rlc_lc_id == TDSRRCLCM_RLC_LC_ID_NOT_FOUND)
    {
      TDSRRC_MSG0(MSG_LEGACY_HIGH,"No SRB4. ");
    }
    else 
    {
      TDSRRC_MSG0(MSG_LEGACY_HIGH,"SRB 4 found");
      return TRUE;
    }
  }
  /* If we get here, we never found that RB id */
  TDSRRC_MSG0(MSG_LEGACY_HIGH,"rb not found in established rabs");
  tdsrrccu_substate = TDSRRCCU_INITIAL;
  tdsrrccu_clear_procedure();
  return FALSE;  
}
/*===========================================================================

FUNCTION RRCCU_CHECK_AND_CLEAR_OC_RESTRICTION

DESCRIPTION
  This function will check whether OC is set. If set then checks whether
  it is OK to reset the OC and if it is OK to reset it will call llc function 
  to clear the oc 

DEPENDENCIES
  None

RETURN VALUE
  boolean
  TRUE  : there is OC restriction 
  FALSE : there is no OC restriction 

SIDE EFFECTS
  None
===========================================================================*/
static tdsrrccu_status_e_type tdsrrccu_check_and_clear_oc_restrictions
(
  tdsrrc_cmd_type *cmd_ptr,
  tdsrrc_CellUpdateCause cell_update_cause
)
{
  tdsrrc_proc_e_type proc_id;
  tdsrrcllc_oc_process_state_e_type  process_state;  
  tdsrrcllc_oc_set_status_e_type     oc_status;
  
  tdsrrc_CellUpdateCause       cu_cause;
  tdsrrccu_re_est_timers_status_e_type cu_tmr_status =  tdsrrccu_check_re_est_timers();
  tdsrrc_cmd_type *llc_cmd_ptr = NULL;  
  

  oc_status = tdsrrcllc_get_ordered_config_state_and_proc(&proc_id, &process_state);
  tdsrrccu_pending_config_proc_id = proc_id;

  if (oc_status != TDSOC_NOT_SET)
  {
    /* check if the OC is set by CU itself and still it is waiting
    for UE to camp on. Inthis case it is OK procede with cell update */
    if ((proc_id == TDSRRC_PROCEDURE_CU) && 
        (tdsrrccu_substate == TDSRRCCU_WAIT_FOR_UE_TO_CAMP_ON))
    {
      return TDSRRCCU_SUCCESS;
    }
    else
    {
      if (process_state == TDSLL_CONFIG_WITH_OC)
      {
        return TDSRRCCU_FAILURE_MAJOR;
      }
      else
      {
        /*lower layers are not configured with oc. get the proc and
        check its status. If it is waiting for L2ack then reset the oc */
        if (TRUE==tdsrrccu_check_proc_waiting_for_l2_ack(proc_id))
        {
          /* If we are driven to Cell_PCH/URA_PCH from Cell_FACH
             we register to cell update to complete routine.
             As OC is going to be reset by CU, reconfig procedures
             would send a failure later */
          if(tdsrrc_get_state() == TDSRRC_STATE_CELL_FACH &&
             (proc_id         == TDSRRC_PROCEDURE_RBE ||
              proc_id         == TDSRRC_PROCEDURE_RBR || 
              proc_id         == TDSRRC_PROCEDURE_RBRC ||
              proc_id         == TDSRRC_PROCEDURE_TCR ||
              proc_id         == TDSRRC_PROCEDURE_PCR)
            )
          {
            if(TDSRRCCU_STARTED == tdsrrccu_get_cell_update_started_status_with_cause(&cu_cause) &&
              (cu_cause == tdsrrc_CellUpdateCause_re_enteredServiceArea || cu_cause == tdsrrc_CellUpdateCause_rlc_unrecoverableError ||
               cu_cause == tdsrrc_CellUpdateCause_radiolinkFailure))
            {
              if(SUCCESS != tdsrrccu_register_for_cell_update_to_complete(proc_id))
              { 
                TDSRRC_MSG0(MSG_LEGACY_ERROR,"Reconfig procedure failed to register with CU");
              }
            }
          }
          TDSRRC_MSG2(MSG_LEGACY_HIGH,"Reset OC status:%d,proc:%d",oc_status,proc_id);
          if (TDSOC_NOT_SET != tdsrrcllc_reset_ordered_config(TDSRRC_PROCEDURE_CU
                                                        ,TRUE
                                                        ))
          {
            TDSRRC_MSG0(MSG_LEGACY_ERROR,"Could not Reset OC");
            return TDSRRCCU_FAILURE_MAJOR;
          }
          else
          {
            return TDSRRCCU_SUCCESS;
          }
        }
        else
        {
          /* procedure is waiting for channel config confirm */
          if (((cell_update_cause != tdsrrc_CellUpdateCause_radiolinkFailure) && (cell_update_cause != tdsrrc_CellUpdateCause_rlc_unrecoverableError)) ||
              !((tdsrrc_get_state() == TDSRRC_STATE_CELL_DCH) && ((oc_status == TDSOC_SET_FOR_CELL_DCH) || (oc_status == TDSOC_SET_FOR_DCH_FACH_TRANS))) ||
              !(tdsrrccu_check_proc_waiting_for_chan_config_cnf(proc_id) ||(oc_status == TDSOC_SET_FOR_DCH_FACH_TRANS)) )
          {
            return TDSRRCCU_FAILURE_MAJOR;
          }
          tdsrrccu_cell_update_cause =  cell_update_cause;
          TDSRRC_MSG1(MSG_LEGACY_HIGH,"Updated CU cause %d",tdsrrccu_cell_update_cause);
          
          if(oc_status == TDSOC_SET_FOR_DCH_FACH_TRANS && (cell_update_cause == tdsrrc_CellUpdateCause_rlc_unrecoverableError || 
              (cell_update_cause == tdsrrc_CellUpdateCause_radiolinkFailure)))
          {
            if(cell_update_cause == tdsrrc_CellUpdateCause_rlc_unrecoverableError)
            {
               tdsrrccu_rb_id_unrec_error = tdsrrclcm_get_ul_rb_id (cmd_ptr->cmd.crlc_status_ind.lc_id);
   
               if ((tdsrrccu_rb_id_unrec_error >= DCCH_AM_RADIO_BEARER_ID) && 
                 (tdsrrccu_rb_id_unrec_error <= DCCH_DT_LOW_PRI_RADIO_BEARER_ID))
               {
                 TDSRRC_MSG1(MSG_LEGACY_HIGH,"rlc error on SRB id%d",tdsrrccu_rb_id_unrec_error);
                 tdsrrccu_rlc_error_info.error_on_srb = TRUE;
               }
               else
               {
                 TDSRRC_MSG1(MSG_LEGACY_HIGH,"rlc error on UplaneRB id%d",tdsrrccu_rb_id_unrec_error);
                 tdsrrccu_rlc_error_info.error_on_urb = TRUE;
               }
            }
            TDSRRC_MSG0(MSG_LEGACY_HIGH,"pending config not cancelled ");
          }
          else
          {
            if((cell_update_cause == tdsrrc_CellUpdateCause_radiolinkFailure) || ((cell_update_cause == tdsrrc_CellUpdateCause_rlc_unrecoverableError)
              && ((tdsrrccu_rb_id_unrec_error = tdsrrclcm_get_ul_rb_id (cmd_ptr->cmd.crlc_status_ind.lc_id)) == DCCH_AM_RADIO_BEARER_ID)))
            { 
              if (cell_update_cause == tdsrrc_CellUpdateCause_rlc_unrecoverableError)
              {
                if ((tdsrrccu_rb_id_unrec_error >= DCCH_AM_RADIO_BEARER_ID) && 
                  (tdsrrccu_rb_id_unrec_error <= DCCH_DT_LOW_PRI_RADIO_BEARER_ID))
                {
                  TDSRRC_MSG1(MSG_LEGACY_HIGH,"rlc error on SRB id%d",tdsrrccu_rb_id_unrec_error);
                  tdsrrccu_rlc_error_info.error_on_srb = TRUE;
                }
                else
                {
                  TDSRRC_MSG1(MSG_LEGACY_HIGH,"rlc error on UplaneRB id%d",tdsrrccu_rb_id_unrec_error);
                  tdsrrccu_rlc_error_info.error_on_urb = TRUE;
                }
              }
  
              /* Before sending cancel req to L1, check these conditions:
               * LLC substate is waiting for CPHY_SETUP_CNF, and not going to old config
               * and T314 and T315 are non-zero with associated RBs
               */
              if((TDSLLC_WAIT_CPHY_SETUP_CNF == tdsrrcllc_return_current_substate()) && 
                !(tdsrrcllc_check_going_to_old_config()) && 
                (tdsrrcllc_check_sufficient_act_time()) &&
                ((cu_tmr_status == TDSRRCCU_T314_T315_NON_ZERO) ||
                (cu_tmr_status == TDSRRCCU_T315_ZERO) || 
                ((cu_tmr_status == TDSRRCCU_T314_ZERO &&
                 tdsrrc_check_rbs_associated_with_re_est_timer(tdsrrc_Re_EstablishmentTimer_useT315)))))
              
              {
  
                TDSRRC_MSG0(MSG_LEGACY_HIGH,"Cancel pending L1 config ");
                if((llc_cmd_ptr = tdsrrc_get_int_cmd_buf()) != NULL)
                {
#ifdef FEATURE_TDSCDMA_RRC_REDUCE_CMD_SIZE
                  llc_cmd_ptr->cmd.rrc_llc_req.l1_req = 
                             (tdsl1_req_cmd *)tdsrrc_malloc(sizeof(tdsl1_req_cmd)); 
                  if(llc_cmd_ptr->cmd.rrc_llc_req.l1_req  == NULL) 
                  {
                      ERR_FATAL("tdsl1_req_cmd not received",0,0,0); 
                  }
#endif
                
                  /* Initialize the LLC command header first */
                  llc_cmd_ptr->cmd_hdr.cmd_id= TDSRRC_LLC_CMD_REQ;
                  llc_cmd_ptr->cmd.rrc_llc_req.procedure = TDSRRC_PROCEDURE_CU;
                  llc_cmd_ptr->cmd.rrc_llc_req.cmd_dest = TDSLAYER1_PHY;
                  llc_cmd_ptr->cmd.rrc_llc_req.l1_cmd.act_time_type = TDSL1_ACTIVATION_TIME_NONE;
                  llc_cmd_ptr->cmd.rrc_llc_req.l1_cmd.cmd_id = TDSL1_CPHY_ACT_TIME_CANCEL_REQ;
                  tdsrrc_put_int_cmd(llc_cmd_ptr); 
                }
                else
                {
                  ERR_FATAL("RRC Unable to get cmd buf for RLC cmd",0,0,0);
                }
              }
              else
              {
                TDSRRC_MSG0(MSG_LEGACY_HIGH,"Unable to cancel pending config take UE to IDLE");
                if( SUCCESS == tdsrrc_transition_to_disconnected_state(TDSRRC_PROCEDURE_CU, 
                                                                    TDSRRC_TX_TO_DISCON_OTHER) )
                {
                  /* Update the release cause */
                  tdsrrc_release_cause = RRC_REL_DEEP_FADE;
                }
                else
                {
                  ERR_FATAL("Failed to go to Disconnected state",0,0,0);
                }
              }
            }
            else
            {
              if (cmd_ptr->cmd_hdr.cmd_id == TDSRRC_CRLC_STATUS_IND)
              {
                /* unrecoverable error on other rbs */
                if ((tdsrrccu_rb_id_unrec_error >= DCCH_AM_RADIO_BEARER_ID) && 
                    (tdsrrccu_rb_id_unrec_error <= DCCH_DT_LOW_PRI_RADIO_BEARER_ID))
                {
                  TDSRRC_MSG1(MSG_LEGACY_HIGH,"rlc error on SRB id%d",tdsrrccu_rb_id_unrec_error);
                  tdsrrccu_rlc_error_info.error_on_srb = TRUE;
                }
                else
                {
                  TDSRRC_MSG1(MSG_LEGACY_HIGH,"rlc error on UplaneRB id%d",tdsrrccu_rb_id_unrec_error);
                  tdsrrccu_rlc_error_info.error_on_urb = TRUE;
                }
              }
              
              TDSRRC_MSG0(MSG_LEGACY_HIGH,"pending config not cancelled ");
              if((TDSRRCCU_T314_T315_ZERO == tdsrrccu_check_re_est_timers()) ||  
                 (TDSRRCCU_T314_ZERO == tdsrrccu_check_re_est_timers() &&
                  !tdsrrc_check_rbs_associated_with_re_est_timer(tdsrrc_Re_EstablishmentTimer_useT315)))
              {
                TDSRRC_MSG0(MSG_LEGACY_HIGH,"Going to idle do to T314 and T315 setting ");
                if( SUCCESS == tdsrrc_transition_to_disconnected_state(TDSRRC_PROCEDURE_CU,
                                                                    TDSRRC_TX_TO_DISCON_OTHER) )
                {
                  /* Update the release cause */
                  tdsrrc_release_cause = RRC_REL_DEEP_FADE;
                }
                else
                {
                  ERR_FATAL("Failed to go to Disconnected state",0,0,0);
                }  
              }
            }
          }

          TDSRRC_MSG0(MSG_LEGACY_HIGH,"move CU to wait for pending config sub state ");
          tdsrrccu_substate = TDSRRCCU_WAIT_FOR_PENDING_CONFIG;
          tdsrrccu_cell_update_started = TRUE;
          return TDSRRCCU_PENDING_CONFIG;
        }
      }
    }
  } /* oc is set */
  else
  {
    return TDSRRCCU_SUCCESS;
  }
}  /* tdsrrccu_check_and_clear_oc_restrictions */


/*===========================================================================

FUNCTION RRCCU_INIT_PROCEDURE

DESCRIPTION
  This function will initialize the Cell Update procedure substate to 
  TDSRRCCU_INITIAL Substate. This will called in the RRCTASK modules 
  along with other Init Procedures.

DEPENDENCIES
  None

RETURN VALUE
  None

SIDE EFFECTS
  None
===========================================================================*/

void tdsrrccu_init_procedure
(    
  void  
)
{
  uint32 i;
  /* Resets the CU state machine */
  tdsrrccu_substate            = TDSRRCCU_INITIAL; 
  tdsrrccu_cell_update_started = FALSE;
  tdsrrccu_ura_update_started  = FALSE;

  tdsrrccu_failure_state                   = TDSRRC_STATE_WILDCARD;
  tdsrrccu_chan_config_reqd                = FALSE;
  tdsrrccu_oc_set_by_cu                    = FALSE;
  tdsrrccu_cell_update_cause               = tdsrrc_CellUpdateCause_cellUpdateCause_ext;

  tdsrrccu_ura_update_cause                = tdsrrc_URA_UpdateCause_spare1;
  tdsrrccu_ura_update_required             = FALSE;
  tdsrrccu_rb_release_info.rrccu_rb_release_in_cucnf = FALSE;

  tdsrrccu_rl_failure_info.t314_info.timer_status         = TDSRE_EST_TIMER_NOT_STARTED;
  tdsrrccu_rl_failure_info.t314_info.need_to_release_rabs = FALSE;
  tdsrrccu_rl_failure_info.t314_info.need_rab_release_ind = FALSE;
  tdsrrccu_rl_failure_info.t315_info.timer_status         = TDSRE_EST_TIMER_NOT_STARTED;
  tdsrrccu_rl_failure_info.t315_info.need_to_release_rabs = FALSE;
  tdsrrccu_rl_failure_info.t315_info.need_rab_release_ind = FALSE;
  tdsrrccu_rlc_error_info.error_on_srb = FALSE;
  tdsrrccu_rlc_error_info.error_on_urb = FALSE;

  /*clear the global variables stored */
  tdsrrccu_cucnf_for_srns_relocation = FALSE;
  tdsrrccu_new_urnti_valid = FALSE;
  tdsrrccu_new_crnti_valid = FALSE;
  tdsrrccu_reestablish_srb = FALSE;
  tdsrrccu_reestablish_srb = FALSE;
  tdsrrccu_reestablish_rab = FALSE;
  tdsrrccu_reestablish_rab = FALSE;

  tdsrrccu_cu_initiate_reqd.cu_reqd = FALSE;
  tdsrrccu_utran_drx_coef  = 0; 
 
 
  tdsrrccu_phy_chan_failure_from_rb = FALSE;
#ifdef FEATURE_RRC_FREQ_REDIRECTION_THRU_RB_AND_CU
  tdsrrccu_int_data.rrccu_cell_selection_trans_from_fach =FALSE;
  tdsrrccu_int_data.rrccu_cell_selection_last_response_msg = TDSRRCCU_NO_RESP_MSG;
  tdsrrccu_int_data.rrccu_cell_selection_last_trans_id = 0xff;
  tdsrrccu_int_data.rrccu_last_cucnf_for_srns_relocation= FALSE;
  tdsrrccu_int_data.rrccu_last_cucnf_cipher_update_required = FALSE;
  tdsrrccu_chan_config_info.num_rbs = 0;
#endif /*FEATURE_RRC_FREQ_REDIRECTION_THRU_RB_AND_CU*/

  /* Set no of registered procedures to zero */
  tdsrrccu_reg_info.no_of_reg_procs = 0;
  tdsrrccu_pending_config_proc_id = TDSRRC_PROCEDURE_NONE;
  tdsrrccu_rb_id_unrec_error = TDSRRC_INVALID_RB_ID; 


  tdsrrccu_int_data.wait_time_in_pch = TDSRRC_T320_INVALID_VALUE;
  tdsrrccu_int_data.cu_cause_for_wait_timer = TDSRRC_CU_CAUSE_NONE;


  /* Initialize all procedures to NULL proecdures */
  for (i = 0; i < (uint32)TDSMAX_NUM_OF_PROCEDURES; i++)
  {
    tdsrrccu_reg_info.rrc_proc[i] = TDSRRC_PROCEDURE_NONE;
  }
  
  tdsrrcscmgr_register_for_scn(TDSRRC_PROCEDURE_CU,
                            TDSRRC_STATE_WILDCARD,
                            TDSRRC_STATE_DISCONNECTED);

  tdsrrcscmgr_register_for_scn(TDSRRC_PROCEDURE_CU,
                            TDSRRC_STATE_CELL_DCH,
                            TDSRRC_STATE_CELL_FACH);

  /* DCH->CELL_PCH state change notification is reqd:
  to start timer t305 */
  tdsrrcscmgr_register_for_scn(TDSRRC_PROCEDURE_CU,
                            TDSRRC_STATE_CELL_DCH,
                            TDSRRC_STATE_CELL_PCH);

  /* DCH->URA_PCH state change notification is reqd:
  to start timer t305
  to Check URA reselection */
  tdsrrcscmgr_register_for_scn(TDSRRC_PROCEDURE_CU,
                            TDSRRC_STATE_CELL_DCH,
                            TDSRRC_STATE_URA_PCH);
  /* FACH->URA_PCH state change notification is reqd:
  to check URA reselection */

  tdsrrcscmgr_register_for_scn(TDSRRC_PROCEDURE_CU,
                            TDSRRC_STATE_CELL_FACH,
                            TDSRRC_STATE_URA_PCH);
  
  /* FACH->CELL_PCH state change notification is reqd:
   */
  tdsrrcscmgr_register_for_scn(TDSRRC_PROCEDURE_CU,
                            TDSRRC_STATE_CELL_FACH,
                            TDSRRC_STATE_CELL_PCH);

  /*register for SIB2 modification notification from SIB proc */
  tdsrrcsibdb_register_for_sib_change_notification ( TDSRRC_PROCEDURE_CU,
                                                tdsrrc_SIB2
                                              );

} /* tdsrrccu_init_procedure */


