 /*===========================================================================

FUNCTION RRCCU_MAP_CU_INITIATION_CAUSE

DESCRIPTION
  This function returns the cellupdate cause defined in rrc asn.1 corresponding to the
  cause received in cell update initiate request from various procedures.


DEPENDENCIES
  None

RETURN VALUE
  tdsrrc_CellUpdateCause cause

SIDE EFFECTS
  None
===========================================================================*/
static tdsrrc_CellUpdateCause tdsrrccu_map_cu_initiation_cause
(
  tdsrrc_cell_update_cause_e_type cause             
)
{
  tdsrrc_CellUpdateCause rrc_cause = tdsrrc_CellUpdateCause_cellUpdateCause_ext;
  switch (cause)
  {
    case TDSRRC_CELL_RESELECTION:
      rrc_cause = tdsrrc_CellUpdateCause_cellReselection;
      break;

    case TDSRRC_PERIODIC_CELL_UPDATE:
      rrc_cause = tdsrrc_CellUpdateCause_periodicalCellUpdate;
      break;

    case TDSRRC_UL_DATA_TRANSMISSION:
      rrc_cause = tdsrrc_CellUpdateCause_uplinkDataTransmission;
      break;

    case TDSRRC_PAGING_RESPONSE:
      rrc_cause = tdsrrc_CellUpdateCause_utran_pagingResponse;
      break;

    case TDSRRC_RADIO_LINK_FAILURE:
      rrc_cause = tdsrrc_CellUpdateCause_radiolinkFailure;
      break;

    case TDSRRC_REENTERED_SERVICE_AREA:
      rrc_cause = tdsrrc_CellUpdateCause_re_enteredServiceArea;
      break;

    case TDSRRC_UNRECOVERABLE_ERROR:
      rrc_cause = tdsrrc_CellUpdateCause_rlc_unrecoverableError;
      break;


#ifdef FEATURE_BPLMN_SEARCH_320MS
    case TDSRRC_LOSSY_PAGE_RECEPTION:
      rrc_cause = tdsrrc_CellUpdateCause_re_enteredServiceArea;
      break;
#endif /*FEATURE_BPLMN_SEARCH_320MS*/

    default:
      TDSRRC_MSG1(MSG_LEGACY_ERROR,"No CU ASN1 cause correspondig to %d",cause); 
      break;
  }
  return rrc_cause;

}
 /*===========================================================================

FUNCTION RRCCU_MAP_UU_INITIATION_CAUSE

DESCRIPTION
  This function returns the uraupdate cause defined in rrc asn.1 corresponding to the
  cause received in ura update initiate request from various procedures.


DEPENDENCIES
  None

RETURN VALUE
  tdsrrc_URA_UpdateCause cause

SIDE EFFECTS
  None
===========================================================================*/
static tdsrrc_URA_UpdateCause tdsrrccu_map_uu_initiation_cause
(
  tdsrrc_ura_update_cause_e_type cause             
)
{
  tdsrrc_URA_UpdateCause rrc_cause = tdsrrc_URA_UpdateCause_spare1;
  switch (cause)
  {
    case TDSRRC_URA_RESELECTION:
      rrc_cause = tdsrrc_URA_UpdateCause_changeOfURA;
      break;

    case TDSRRC_PERIODIC_URA_UPDATE:
      rrc_cause = tdsrrc_URA_UpdateCause_periodicURAUpdate;
      break;

    default:
      TDSRRC_MSG1(MSG_LEGACY_ERROR,"No UU ASN1 cause correspondig to %d",cause); 
      rrc_cause = tdsrrc_URA_UpdateCause_spare1;
      break;
  }
  return rrc_cause;
}  /* tdsrrccu_map_uu_initiation_cause */

/*===========================================================================

FUNCTION tdsrrccu_send_ura_update_initiate_req

DESCRIPTION
  This function sends the ura update initiate request 

DEPENDENCIES
  None.

RETURN VALUE
  None.

===========================================================================*/
static void tdsrrccu_send_ura_update_initiate_req
(
tdsrrc_ura_update_cause_e_type  cause,
boolean                      cnf_reqd
)
{
  tdsrrc_cmd_type *int_cmd_ptr;

  if ( (int_cmd_ptr =  tdsrrc_get_int_cmd_buf()) != NULL)
  {
    /* Fill in the command parameters for TDSRRC_CELL_UPDATE_INITIATE_REQ */
    int_cmd_ptr->cmd_hdr.cmd_id                                   = TDSRRC_URA_UPDATE_INITIATE_REQ;
    int_cmd_ptr->cmd.initiate_ura_update.cause                    = cause;
    int_cmd_ptr->cmd.initiate_ura_update.uu_complete_cnf_required = cnf_reqd;
    int_cmd_ptr->cmd.initiate_ura_update.procedure                = TDSRRC_PROCEDURE_CU;
    TDSRRC_MSG2(MSG_LEGACY_HIGH,"URA_UPDATE_INITIATE  Cause:%d,cnf_reqd:%d",cause,cnf_reqd);
    tdsrrc_put_int_cmd(int_cmd_ptr);             
  }
  else
  {
    ERR_FATAL("Unable to allocate memmory for: %d cmd",TDSRRC_URA_UPDATE_INITIATE_REQ,0,0);
  }
}/*tdsrrccu_send_ura_update_initiate_req*/

/*===========================================================================

FUNCTION RRCCU_CONVERT_T307_TO_MS

DESCRIPTION
  This function converts the tdsrrc_T_307 enums to milliseconds

DEPENDENCIES
  None

RETURN VALUE
  uint32

SIDE EFFECTS
  None
===========================================================================*/
uint32 tdsrrccu_convert_t307_to_ms
(
  tdsrrc_T_307 rrccu_t_307                    /* enum for Timer T307 */
)
{
  uint32 timer_value;                         /* Timer Value in milli seconds */

  switch (rrccu_t_307)
  {
    case tdsrrc_T_307_s5:
      timer_value = 5000;
      break;
    case tdsrrc_T_307_s10:
      timer_value = 10000;
      break;      
    case tdsrrc_T_307_s15:
      timer_value = 15000;
      break;
    case tdsrrc_T_307_s20:
      timer_value = 20000;
      break;
    case tdsrrc_T_307_s30:
      timer_value = 30000;
      break;
    case tdsrrc_T_307_s40:
      timer_value = 40000;
      break; 
    case tdsrrc_T_307_s50:
      timer_value = 50000;
      break;
    default:
      TDSRRC_MSG0(MSG_LEGACY_HIGH,"Unknown Timer value received ");
      timer_value = 0;                  /* Set lowest timer value as a default */
      break;
  }
  return (timer_value);
} /* tdsrrccu_convert_t307_to_ms*/
