/*===========================================================================

FUNCTION RRCCU_DELETE_CRNTI

DESCRIPTION
  This function sends TDSRRC_RNTI_UPDATE_REQ to RRC LLC to delete the C-RNTI
  
DEPENDENCIES


RETURN VALUE
  tdsrrccu_status_e_type: returns TDSRRCCU_SUCCESS if it successfully sends
  TDSRRC_CHANNEL_CONFIG_REQ to the RRC LLC. Otherwise it returns
  TDSRRCCU_FAILURE_MAJOR.


SIDE EFFECTS

  None

===========================================================================*/
void tdsrrccu_delete_crnti
(  
  void
)
{
  tdsrrc_cmd_type *cmd_ptr;                     /* Pointer to the RRC Command */

  /* Allocates the buffer to RRC Internal command */
  if( (cmd_ptr =  tdsrrc_get_int_cmd_buf()) != NULL)
  {     
    /* Fill in the command parameters for TDSRRC_CHANNEL_CONFIG_REQ */
    cmd_ptr->cmd_hdr.cmd_id = TDSRRC_RNTI_UPDATE_REQ;
    cmd_ptr->cmd.rnti_update_req.procedure = TDSRRC_PROCEDURE_CU;

    /* Fill in parameters for TDSRRC_RNTI_UPDATE_REQ command */
    cmd_ptr->cmd.rnti_update_req.crnti_action = TDSRRC_RNTI_DELETE;

    cmd_ptr->cmd.rnti_update_req.urnti_action = TDSRRC_RNTI_NOCHANGE;
    cmd_ptr->cmd.rnti_update_req.cnf_required = FALSE;
   
    cmd_ptr->cmd.rnti_update_req.rlc_re_establish_rab = FALSE;
    cmd_ptr->cmd.rnti_update_req.rlc_re_establish_srb = FALSE;

    cmd_ptr->cmd.chan_config_req.rrc_channel_config_cnf_required = FALSE;
  
    tdsrrc_put_int_cmd(cmd_ptr);                 /* sends the command to RRC
                                                 LLC. */
  }
  else  /* RRC Task failed to allocate memory */
  {
    ERR_FATAL("Unable to allocate memory for cmd: %d",TDSRRC_RNTI_UPDATE_REQ,0,0);
  }
} /* tdsrrccu_delete_crnti */

