/*===========================================================================

FUNCTION RRCCU_PROCESS_DISCONNECTED_STATE

DESCRIPTION
  This function processes all events that are dispatched to Cell Update 
  procedure in DISCONNECTED state of Idle  mode.

  
DEPENDENCIES
  None

RETURN VALUE
  None
  
SIDE EFFECTS

  None

===========================================================================*/
void tdsrrccu_process_disconnected_state
(  
  tdsrrc_cmd_type *cmd_ptr
)
{   

  if(cmd_ptr->cmd_hdr.cmd_id == TDSRRC_STATE_CHANGE_IND)
  {
    /* On a change of state to Disconnected, clear the
     * Cell Update substate upfront, irrespective of 
     * current Cell Update substate. This is to 
     * rule out any possibility of a "hung" Cell Update.
     */
    TDSRRC_MSG2(MSG_LEGACY_HIGH,"state change ind cu_st:%d cu_cause:%d",tdsrrccu_substate,tdsrrccu_cell_update_cause);
    if(cmd_ptr->cmd.state_change_ind.new_state ==
        TDSRRC_STATE_DISCONNECTED)
    {
      tdsrrctmr_stop_timer(TDSRRCTMR_T_305_TIMER);

      tdsrrctmr_stop_timer(TDSRRCTMR_T_302_TIMER);


      /*stop T314 and T315 timers if they are started */
      if (tdsrrccu_substate != TDSRRCCU_INITIAL)  
      {
        switch (tdsrrccu_cell_update_cause)
        {
          case  tdsrrc_CellUpdateCause_radiolinkFailure:
          case  tdsrrc_CellUpdateCause_rlc_unrecoverableError:
          case  tdsrrc_CellUpdateCause_re_enteredServiceArea:
            if (tdsrrccu_failure_state == TDSRRC_STATE_CELL_DCH)
            {
              TDSRRC_MSG0(MSG_LEGACY_HIGH,"Stop re-est timers");
              tdsrrctmr_stop_timer(TDSRRCTMR_T_314_TIMER);
              tdsrrctmr_stop_timer(TDSRRCTMR_T_315_TIMER);
            }
            /* UE must have gone out of service area during
            RL failure handling */
            if ((tdsrrccu_substate == TDSRRCCU_WAIT_FOR_UE_TO_CAMP_ON) ||
                (tdsrrccu_substate == TDSRRCCU_WAIT_FOR_RB_REL_CNF))
            {
              TDSRRC_MSG0(MSG_LEGACY_HIGH,"Stop OOS timers");
              tdsrrctmr_stop_timer(TDSRRCTMR_T_307_TIMER);
              tdsrrctmr_stop_timer(TDSRRCTMR_T_317_TIMER);
              /* stop the oos timer */
              tdsrrctmr_stop_timer(TDSRRCTMR_T_OOS_TIMER);
            }
            break;

          default:
            break;
        }
      }
      tdsrrccu_substate = TDSRRCCU_INITIAL;            
      /*call the procedure to clear the global variabls */
      tdsrrccu_clear_procedure();
#ifdef FEATURE_RRC_FREQ_REDIRECTION_THRU_RB_AND_CU
      tdsrrccu_init_last_cu_cnf_info();
#endif /*FEATURE_RRC_FREQ_REDIRECTION_THRU_RB_AND_CU*/

      tdsrrccu_reset_registration_info();
      return;
    }
  }

  switch (tdsrrccu_substate)
  {      
    case TDSRRCCU_INITIAL:
      tdsrrccu_process_cu_initial(cmd_ptr);
      break;
    case TDSRRCCU_WAIT_FOR_UE_TO_CAMP_ON:
      tdsrrccu_process_cu_wait_for_ue_to_camp_on(cmd_ptr);
      break;
    case TDSRRCCU_WAIT_FOR_RB0_EST_CNF:
      tdsrrccu_process_cu_wait_for_rb0_est_cnf(cmd_ptr);
      break;
    case TDSRRCCU_WAIT_FOR_CELL_UPDATE_CONFIRM:
      tdsrrccu_process_cu_wait_for_cell_update_confirm(cmd_ptr);
      break;
    case TDSRRCCU_WAIT_FOR_RB_EST_CNF:
      tdsrrccu_process_cu_wait_for_rb_est_cnf(cmd_ptr);
      break;
    case TDSRRCCU_WAIT_FOR_RB_REL_CNF:
      tdsrrccu_process_cu_wait_for_rb_rel_cnf(cmd_ptr);
      break;
    case TDSRRCCU_WAIT_FOR_L2_ACK:
      tdsrrccu_process_cu_wait_for_l2_ack(cmd_ptr);
      break;
    default:
      TDSRRC_MSG2(MSG_LEGACY_ERROR,"Invalid CU st %d for DISCONN for cmd %d",tdsrrccu_substate,cmd_ptr->cmd_hdr.cmd_id);
      break; 
  }
} 
/* tdsrrccu_process_disconnected_state */
