/*===========================================================================

FUNCTION tdsrrccu_establish_tm_um_srb

DESCRIPTION
  This function sends TDSRRC_CHANNEL_CONFIG_REQ to RRC LLC to establish RB0
  and RB1 to RB4 if the RB mapping info of these signalling RBs on FACH
  is available. rrcllc will decide whether to setup RB1 to RB4 along with RB0
  
DEPENDENCIES


RETURN VALUE
  tdsrrccu_status_e_type: returns TDSRRCCU_SUCCESS if it successfully sends
  TDSRRC_CHANNEL_CONFIG_REQ to the RRC LLC. Otherwise it returns
  TDSRRCCU_FAILURE_MAJOR.


SIDE EFFECTS

  None

===========================================================================*/
void tdsrrccu_establish_tm_um_srb
(    
  boolean pch_to_fach_transition,
  tdsrrc_state_e_type dest_state,                /* Next state to transition is
                                                 expected to take place */
  boolean confirm_required                    /* This indicates whether
                                                 TDSRRC_CHANNEL_CONFIG_CNF is 
                                                 required or not */  
)
{
  tdsrrc_cmd_type *cmd_ptr;                     /* Pointer to the RRC Command */
  uint32 count=0;

#ifdef FEATURE_TDSCDMA_SRB5_SUPPORT
  tdsrrc_RB_Identity srb5_rb_id;
#endif /* FEATURE_TDSCDMA_SRB5_SUPPORT */

  /* Allocates the buffer to RRC Internal command */
  if( (cmd_ptr =  tdsrrc_get_int_cmd_buf()) != NULL)
  {     
    /* Fill in the command parameters for TDSRRC_CHANNEL_CONFIG_REQ */
    cmd_ptr->cmd_hdr.cmd_id = TDSRRC_CHANNEL_CONFIG_REQ;
    cmd_ptr->cmd.chan_config_req.procedure = TDSRRC_PROCEDURE_CU;
    cmd_ptr->cmd.chan_config_req.next_state = dest_state;
    cmd_ptr->cmd.chan_config_req.rrc_channel_config_cnf_required = 
      confirm_required;

    /* Fill in parameters for TDSRRC_CHANNEL_CONFIG_REQ command */
    /* if Pch->fach transition then state change is required and also
    need to release pcch and add ccch */
    if (pch_to_fach_transition)
    {
      {
      cmd_ptr->cmd.chan_config_req.rrc_state_change_required = TRUE;
      cmd_ptr->cmd.chan_config_req.rb[count].rb_id = PCCH_RADIO_BEARER_ID;
      cmd_ptr->cmd.chan_config_req.rb[count++].rb_config = TDSRELEASE_RB;
      cmd_ptr->cmd.chan_config_req.rb[count].rb_id = CCCH_RADIO_BEARER_ID;
      cmd_ptr->cmd.chan_config_req.rb[count++].rb_config = TDSRECONFIG_RB;
      cmd_ptr->cmd.chan_config_req.chan_config_reason = TDSRRCLLC_CHAN_CFG_REASON_PCH_TO_FACH;
      }
    }
    else
    {
      cmd_ptr->cmd.chan_config_req.rrc_state_change_required = FALSE;
      cmd_ptr->cmd.chan_config_req.chan_config_reason = TDSRRCLLC_CHAN_CFG_REASON_RL_FAILURE;
    }
    /*reconfig signalling RBs */
    cmd_ptr->cmd.chan_config_req.rb[count].rb_id = DCCH_UM_RADIO_BEARER_ID;
    cmd_ptr->cmd.chan_config_req.rb[count++].rb_config = TDSRECONFIG_RB;


#ifdef FEATURE_TDSCDMA_SRB5_SUPPORT
    if(tdsrrclcm_get_rb_id_if_dl_lc_type_exists(UE_LOGCHAN_TM_DCCH_DL, &srb5_rb_id) == TDSRRCLCM_SUCCESS)
    {
      cmd_ptr->cmd.chan_config_req.rb[count].rb_id       = srb5_rb_id;
      cmd_ptr->cmd.chan_config_req.rb[count++].rb_config = TDSRECONFIG_RB;
    }
#endif /* FEATURE_TDSCDMA_SRB5_SUPPORT */
    
    /* set both rab release flags to false as the "TRUE" case is 
    taken care in the above loop */
    cmd_ptr->cmd.chan_config_req.num_rb_to_config        = (uint16)count;
  
    TDSRRC_MSG1(MSG_LEGACY_HIGH,"TDSRRC_CHANNEL_CONFIG_REQ sent to establish %dRBs for temeporary FACH state ",count);
    tdsrrc_put_int_cmd(cmd_ptr);                 /* sends the command to RRC
                                                 LLC. */
  }
  else  /* RRC Task failed to allocate memory */
  {
    ERR_FATAL("Unable to allocate memory for cmd: %d",TDSRRC_CHANNEL_CONFIG_REQ,0,0);
  }
}
/*===========================================================================

FUNCTION tdsrrccu_fill_rb_id_for_fach_state

DESCRIPTION
  This function fill another RBs which is not in the affect and reconfiguration list
  in Cell_FACH state.
  
DEPENDENCIES


RETURN VALUE
  tdsrrccu_status_e_type: returns TDSRRCCU_SUCCESS if it successfully sends
  TDSRRC_CHANNEL_CONFIG_REQ to the RRC LLC. Otherwise it returns
  TDSRRCCU_FAILURE_MAJOR.


SIDE EFFECTS

  None

===========================================================================*/
void tdsrrccu_fill_rb_id_for_fach_state(uint32 *rb_count,
  tdsrrc_channel_config_req_type *chan_config_req,
  boolean srb_reest_ind,
  boolean urb_reest_ind)
{
  uint8 i=0;
  uint8 count = 0;
  uint8 urb_count = 0;
  uint8 rab_count = 0;
  tdsrrc_channel_config_req_type tmp_chan_config_req={0};

  rlc_lc_id_type ul_rlc_lc_id = TDSRRCLCM_RLC_LC_ID_NOT_FOUND;
    /* Fill in parameters for TDSRRC_CHANNEL_CONFIG_REQ command */
    /* if Pch->fach transition then state change is required and also
    need to release pcch and add ccch */
  if(srb_reest_ind == FALSE)
  {
    /*reconfig signalling RBs */
    tmp_chan_config_req.rb[count].rb_id = DCCH_AM_RADIO_BEARER_ID;
    tmp_chan_config_req.rb[count++].rb_config = TDSRECONFIG_RB;
    tmp_chan_config_req.rb[count].rb_id = DCCH_DT_HIGH_PRI_RADIO_BEARER_ID;
    tmp_chan_config_req.rb[count++].rb_config = TDSRECONFIG_RB;

    /* check whether RB4 was present or not */
    ul_rlc_lc_id = tdsrrclcm_check_ul_rlc_lc_id(UE_LOGCHAN_DCCH, 
                                 DCCH_DT_LOW_PRI_RADIO_BEARER_ID,
                                 UE_MODE_ACKNOWLEDGED_DATA);

    if(ul_rlc_lc_id == TDSRRCLCM_RLC_LC_ID_NOT_FOUND)
    {
      TDSRRC_MSG0(MSG_LEGACY_HIGH,"No RB4 in CELL_FACH");
    }
    else 
    {
      tmp_chan_config_req.rb[count].rb_id = DCCH_DT_LOW_PRI_RADIO_BEARER_ID;
      tmp_chan_config_req.rb[count++].rb_config = TDSRECONFIG_RB;
    }
  }
    /*setup the user plane RBs also at this time. Do not have to worry about the
    ul transmission as it will not happen until we get a valid C-RNTI in the 
    cell update confirm message */
  if(urb_reest_ind == FALSE)
  {
    for (rab_count=0; rab_count<MAX_RAB_TO_SETUP; rab_count++)
    {
      if (((tdsrrc_est_rabs.rabs[rab_count].cn_domain == RRC_CS_DOMAIN_CN_ID)|| 
             (tdsrrc_est_rabs.rabs[rab_count].cn_domain == RRC_PS_DOMAIN_CN_ID))
            &&(tdsrrc_est_rabs.rabs[rab_count].num_rbs_for_rab > 0)
          )
      {
        /*it is a valid established rab, now compare each rb-id in this established rab with 
        the rb-id received in the message */
        for (i=0; ((i<tdsrrc_est_rabs.rabs[rab_count].num_rbs_for_rab) && 
               (i < MAX_RB_PER_RAB)&&(count < TDS_MAX_RB)); i++)    
        {
          
          tmp_chan_config_req.rb[count].rb_id = 
            tdsrrc_est_rabs.rabs[rab_count].rb_for_rab[i].rb_id;
          TDSRRC_MSG1(MSG_LEGACY_HIGH,"Fill RB %d from all RABs",tmp_chan_config_req.rb[count].rb_id);
          tmp_chan_config_req.rb[count++].rb_config = TDSRECONFIG_RB;

          urb_count++;
        }
      } /*end of if*/
    }/* rab_count loop */
  }
    /* set both rab release flags to false as the "TRUE" case is 
    taken care in the above loop */
    tmp_chan_config_req.num_rb_to_config        = (uint16)count;
  TDSRRC_MSG1(MSG_LEGACY_HIGH,"The No of tmp RBs is %d ",count);
  for(i = 0; (i < tmp_chan_config_req.num_rb_to_config)&&(*rb_count < TDS_MAX_RB)&&(i<TDS_MAX_RB); i++)
  {
    if(TDS_MAX_RB == tdsrrcllc_check_if_rbid_present_in_chan_config(chan_config_req,
        tmp_chan_config_req.rb[i].rb_id))
    {
      TDSRRC_MSG1(MSG_LEGACY_HIGH,"Fill RB %d from all RBs",tmp_chan_config_req.rb[i].rb_id);
      chan_config_req->rb[(*rb_count)].rb_id = tmp_chan_config_req.rb[i].rb_id;
      chan_config_req->rb[(*rb_count)].rb_config = TDSRECONFIG_RB;
      chan_config_req->rb[(*rb_count)].ul_cfg_mask = TDSMODIFY_RB_CFG;
      chan_config_req->rb[(*rb_count)].dl_cfg_mask = TDSMODIFY_RB_CFG;
      (*rb_count)++; 
    }
  }
  chan_config_req->num_rb_to_config = (int) *rb_count;
}


#endif

/*===========================================================================

FUNCTION tdsrrccu_clear_pending_cu_procedure

DESCRIPTION
  This function clear the CU state, variable.
  
DEPENDENCIES


RETURN VALUE
  void


SIDE EFFECTS

  None

===========================================================================*/
void tdsrrccu_clear_pending_cu_procedure(void)
{
  /* Stop timer T305 */
    tdsrrctmr_stop_timer(TDSRRCTMR_T_305_TIMER);  
    /* stop timer t302 if cu proc is waiting for cucnf.*/
    if (tdsrrccu_substate == TDSRRCCU_WAIT_FOR_CELL_UPDATE_CONFIRM || 
        tdsrrccu_substate == TDSRRCCU_WAIT_FOR_URA_UPDATE_CONFIRM)
    {
      tdsrrctmr_stop_timer(TDSRRCTMR_T_302_TIMER);
    }

    /*stop T314 and T315 timers if they are started */
    if (tdsrrccu_substate != TDSRRCCU_INITIAL)  
    {
      switch (tdsrrccu_cell_update_cause)
      {
        case  tdsrrc_CellUpdateCause_radiolinkFailure:
        case  tdsrrc_CellUpdateCause_re_enteredServiceArea:
          tdsrrctmr_stop_timer(TDSRRCTMR_T_307_TIMER);
          tdsrrctmr_stop_timer(TDSRRCTMR_T_317_TIMER);
          /* stop the oos timer */
          tdsrrctmr_stop_timer(TDSRRCTMR_T_OOS_TIMER);
          /* do not break, fall through */

        case  tdsrrc_CellUpdateCause_rlc_unrecoverableError:
          if (tdsrrccu_failure_state == TDSRRC_STATE_CELL_DCH)
          {
            TDSRRC_MSG0(MSG_LEGACY_HIGH,"Stop re-est timers");
            tdsrrctmr_stop_timer(TDSRRCTMR_T_314_TIMER);
            tdsrrctmr_stop_timer(TDSRRCTMR_T_315_TIMER);
          }
          break;

        default:
          break;
      }
    }
    /* Reset CU Procedure and  Procedure ends */
    tdsrrccu_substate = TDSRRCCU_INITIAL; 
    /*call the procedure to clear the global variabls */
    tdsrrccu_clear_procedure();
    return;
}
/*===========================================================================

FUNCTION tdsrrccu_get_reestablish_timer

DESCRIPTION
  This function get the re-establish timer length.
  
DEPENDENCIES


RETURN VALUE
  void


SIDE EFFECTS

  None

===========================================================================*/
uint32 tdsrrccu_get_reestablish_timer(void)
{
  uint8 count= 0;
  tdsrrc_Re_EstablishmentTimer reest_timer = 0xFFFFFFFF;
  
  for (count = 0; count < MAX_RAB_TO_SETUP; count++)
  {
    if( (tdsrrc_est_rabs.rabs[count].cn_domain == RRC_PS_DOMAIN_CN_ID) &&
        (tdsrrc_est_rabs.rabs[count].num_rbs_for_rab > 0) )
    {
       /* Assume TDS NW one domain only use one timer. */
       reest_timer = tdsrrc_est_rabs.rabs[count].re_est_timer;
       break;
    }
  }
  if (reest_timer == tdsrrc_Re_EstablishmentTimer_useT315)
  {
    return tdsrrccu_convert_t315_to_ms( TDSRRC_GET_T315());
  }
  else if(reest_timer == tdsrrc_Re_EstablishmentTimer_useT314)
  {
    return tdsrrccu_convert_t314_to_ms( TDSRRC_GET_T314());
  }
  /* No PS RAB exist */
  else
  {
	/* Use T315 if PS session is open*/
	if(tdsrrcdt_is_ps_domain_open())
	{
      return tdsrrccu_convert_t315_to_ms( TDSRRC_GET_T315());
	}
	/*Use T314 if there is only CS session open*/
	else if (tdsrrcdt_is_cs_domain_open())
	{
      return tdsrrccu_convert_t314_to_ms( TDSRRC_GET_T314());
	}
	/*If there is no RAB exist and only RRc connection, return T314 for CS domain RRC connection, T315 for PS domain RRC connection*/
	else if (tdsrrc_est_cn_domain_id == RRC_CS_DOMAIN_CN_ID)
	{
	  return tdsrrccu_convert_t314_to_ms( TDSRRC_GET_T314());
	}
	else if (tdsrrc_est_cn_domain_id == RRC_PS_DOMAIN_CN_ID)
	{
	  return tdsrrccu_convert_t315_to_ms( TDSRRC_GET_T315());
	}
  }
  return 0;
}



/*===========================================================================

FUNCTION tdsrrccu_check_cu_active_before_lock_rel

DESCRIPTION 
  This procedure is used to query if CU is active for UL Data Transmission,
  Periodic Cell Update, Paging Response 

DEPENDENCIES
    None.

RETURN VALUE
   NONE
successful.

===========================================================================*/

boolean tdsrrccu_check_cu_active_before_lock_rel(void)
{
  boolean status=FALSE;  

  if((tdsrrccu_get_cell_update_started_status()== TDSRRCCU_STARTED) 
   &&((tdsrrccu_cell_update_cause == tdsrrc_CellUpdateCause_uplinkDataTransmission)||
      (tdsrrccu_cell_update_cause == tdsrrc_CellUpdateCause_utran_pagingResponse)||
      (tdsrrccu_cell_update_cause == tdsrrc_CellUpdateCause_periodicalCellUpdate)||
      (tdsrrccu_ura_update_cause == tdsrrc_URA_UpdateCause_periodicURAUpdate)))
  {

   /* When CU cause is rrc_CellUpdateCause_cellReselection & rrc_CellUpdateCause_re_enteredServiceArea,
      CU module will decide if lock acquiring is needed after it receives NEW_CELL_IND. 
      Thus CSP releases the lock as its uncertain whether CU will be triggered.
    */ 
    status=TRUE;
  }
  return status;  
}

/*===========================================================================   
      FUNCTION tdsrrccu_post_buffered_commands
      
      DESCRIPTION
        
      This function will post commands buffered when UE was in standby state.
        
      DEPENDENCIES
        None
      
      RETURN VALUE
        None
      SIDE EFFECTS
      
        None
      
===========================================================================*/

void tdsrrccu_post_buffered_commands(void)
{ 
  TDSRRC_MSG1(MSG_LEGACY_HIGH,"Post %d from buffered indication",tdsrrccu_buffered_cmd_mask);
  if(tdsrrccu_buffered_cmd_mask & TDSRRCCU_UL_DATA_IND)
  {
      tdsrrccu_rlc_ul_data_ind(NULL,NULL);
      /* Need not send SIB-change/t305 expiry if UL data ind is sent even if it is buffered*/
  }
  else if(tdsrrccu_buffered_cmd_mask & TDSRRCCU_CU_INITIATE_REQ)
  {
      tdsrrccu_post_cu_initiate_req();
  }
  else if(tdsrrccu_buffered_cmd_mask & TDSRRCCU_T305_EXPIRY_IND)
  {
      tdsrrccu_post_t305_expiry_ind();
      /*Need not send sib change ind if t305 expiry is sent even if it is buffered 
        Prioritize t305 expiry because this will always trigger CU, where as sib change ind 
        triggers CU only if there is a URA change 
       */
  }  
  else if(tdsrrccu_buffered_cmd_mask & TDSRRCCU_SIB_CHANGE_IND)
  {
      tdsrrccu_post_sib_change_ind();
  }
  /* Reset the mask */
  tdsrrccu_buffered_cmd_mask = 0;  
  memset(&tdsrrccu_buffered_cu_initiate_req,0,sizeof(tdsrrc_initiate_cu_req_type));
}

/*===========================================================================

FUNCTION tdsrrccu_check_and_set_v302_when_T302_expired_during_acquire_lock

DESCRIPTION 
  This procedure is used to check and set v302,if it exeed n302,set tdsrrc_reestablish_timer_out to TRUE

DEPENDENCIES
    None.

RETURN VALUE
   NONE
successful.

===========================================================================*/

void tdsrrccu_check_and_set_v302_when_T302_expired_during_acquire_lock(void)
{
  if(tdsrrc_v_302 <= TDSRRC_GET_N302())
  {
    tdsrrctmr_start_timer(TDSRRCTMR_T_302_TIMER, tdsrrccu_convert_t302_to_ms(TDSRRC_GET_T302()));    
    /* Increment re-transmission counter */
    tdsrrc_v_302++;
  }
  else
  {
    tdsrrcmcm_set_reestablish_timer_out();
  }
}
